import{_ as e,o as a,c as r,a0 as n}from"./chunks/framework.BQGW-Zpy.js";const p=JSON.parse('{"title":"Alternative Approaches to Cross-Border Settlement","description":"","frontmatter":{},"headers":[],"relativePath":"business/alternative-approaches.md","filePath":"business/alternative-approaches.md"}'),i={name:"business/alternative-approaches.md"};function o(s,t,l,d,c,h){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="alternative-approaches-to-cross-border-settlement" tabindex="-1">Alternative Approaches to Cross-Border Settlement <a class="header-anchor" href="#alternative-approaches-to-cross-border-settlement" aria-label="Permalink to &quot;Alternative Approaches to Cross-Border Settlement&quot;">​</a></h1><p>Two different questions, easy to conflate: which <em>companies</em> compete with this project (see <a href="./market-analysis.html">Market Analysis</a> for that), and which <em>systemic models</em> solve the same underlying problem by a completely different mechanism. This page is the second question: real, currently-being-built alternatives at the infrastructure and institutional level, not company competitors.</p><h2 id="model-comparison" tabindex="-1">Model comparison <a class="header-anchor" href="#model-comparison" aria-label="Permalink to &quot;Model comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Model</th><th>Mechanism</th><th>Who is building it</th><th>Where it works today</th></tr></thead><tbody><tr><td><strong>This project</strong></td><td>Stablecoin settlement rail + licensed on/off-ramp partners, anchored on Hedera</td><td>Us</td><td>Any corridor with a licensed payout partner, regardless of destination banking infrastructure</td></tr><tr><td><strong>Bilateral fast-payment linkage</strong></td><td>Direct handshake between two countries&#39; domestic instant payment systems</td><td>India&#39;s NPCI (UPI-PayNow with Singapore; also UAE, France, Bhutan, Nepal, Sri Lanka, Mauritius)</td><td>Only between countries that already have a domestic instant payment system and have negotiated a bilateral link</td></tr><tr><td><strong>Multilateral fast-payment hub</strong></td><td>One integration point connecting many countries&#39; instant payment systems under shared governance</td><td>Project Nexus (BIS), connecting India, Malaysia, the Philippines, Singapore, Thailand</td><td>Same constraint as bilateral, but scales better once built; still requires each country to already run a domestic instant payment system</td></tr><tr><td><strong>Regional payment mesh</strong></td><td>A bloc-wide network of linked domestic QR/instant systems</td><td>ASEAN (PromptPay, QRIS, PayNow, DuitNow), under the 2023 Regional Payment Connectivity declaration</td><td>Southeast Asia specifically, where this mesh already has years of bilateral links to build on</td></tr><tr><td><strong>Multi-CBDC platform (wholesale)</strong></td><td>Central banks issue and exchange CBDCs directly on a shared DLT platform</td><td>mBridge (PBOC, Hong Kong Monetary Authority, Bank of Thailand, Central Bank of UAE, SAMA)</td><td>Wholesale/interbank only, and only between participating central banks. No Western central bank participates</td></tr><tr><td><strong>Multi-CBDC platform (G7-aligned)</strong></td><td>Same wholesale concept, different political alignment</td><td>Project Agora (BIS + 7 G7 central banks + 40+ institutions incl. JPMorgan, Citi, HSBC, SWIFT)</td><td>Still in testing; results expected H1 2026, not yet live</td></tr></tbody></table><h2 id="why-the-fast-payment-and-cbdc-models-don-t-compete-directly-with-this-project" tabindex="-1">Why the fast-payment and CBDC models don&#39;t compete directly with this project <a class="header-anchor" href="#why-the-fast-payment-and-cbdc-models-don-t-compete-directly-with-this-project" aria-label="Permalink to &quot;Why the fast-payment and CBDC models don&#39;t compete directly with this project&quot;">​</a></h2><p>Every model above except this project&#39;s requires <strong>infrastructure that doesn&#39;t exist in most of the corridors this project targets</strong>. UPI-PayNow, Project Nexus, and the ASEAN mesh all connect countries that <em>already</em> run a domestic instant payment system (UPI, PayNow, PromptPay, QRIS, DuitNow), a precondition most of Africa, and much of Latin America, does not yet meet. mBridge and Agora are wholesale, interbank platforms; neither touches a retail freelancer or SME payment.</p><p><strong>This is the actual competitive positioning:</strong> this project&#39;s model is not a smaller or earlier version of Nexus or mBridge. It solves a structurally different problem: settlement where no domestic instant-payment or CBDC infrastructure exists yet to link to, by routing through a licensed commercial partner instead of a central bank or national payment operator. Where Nexus-style linkage <em>does</em> exist (Southeast Asia increasingly), it is very likely cheaper and faster than this project&#39;s model, because it removes an intermediary layer entirely. <strong>Note: this project&#39;s addressable market shrinks over time as bilateral and multilateral fast-payment links expand, and grows in the corridors those links haven&#39;t reached yet.</strong></p><h2 id="sourced-figures-mid-2026-re-verify-before-final-citation" tabindex="-1">Sourced figures (mid-2026, re-verify before final citation) <a class="header-anchor" href="#sourced-figures-mid-2026-re-verify-before-final-citation" aria-label="Permalink to &quot;Sourced figures (mid-2026, re-verify before final citation)&quot;">​</a></h2><ul><li>mBridge: ~$55.5B processed across 4,047 transactions as of Nov 2025 (Atlantic Council, via PYMNTS, Jan 2026); ~95% settled in digital yuan; participants are PBOC, HKMA, Bank of Thailand, Central Bank of UAE, and SAMA (joined 2024). No Western central bank.</li><li>Project Agora: 7 G7-aligned central banks + 40+ private institutions (JPMorgan, Citi, HSBC, SWIFT); testing phase results expected H1 2026</li><li>UPI cross-border links: Singapore, UAE, France, Bhutan, Nepal, Sri Lanka, Mauritius live; 10+ corridors targeted by end of 2026; cross-border UPI volume grew from 37,060 transactions (FY24) to 755,000+ (FY25)</li><li>ASEAN Regional Payment Connectivity: PromptPay, QRIS, PayNow, DuitNow linked since the 2023 Leaders&#39; Declaration, full ASEAN interoperability targeted</li></ul>',9)])])}const u=e(i,[["render",o]]);export{p as __pageData,u as default};
